// Generated by Cypress Author on 2026-10-23 for IMP-03 in the main application.
import {
  preparePractice,
  openPractice,
  writeCode,
  correctCode,
  attemptsEndpoint,
} from './practice-support';

describe('IMP-03 · práctica con API y ejecutor Docker reales', () => {
  it('IMP03-01 · Ejecutar y editar durante la respuesta → resultado temporal sin progreso ni intento', () => {
    preparePractice().then((fixture) => {
      const endpoint = attemptsEndpoint(fixture).replace(
        '/attempts',
        '/executions',
      );
      // Delay delivery only; the API and runner still produce the real result.
      cy.intercept('POST', `**${endpoint}`, (request) =>
        request.continue((response) => {
          response.setDelay(1000);
        }),
      ).as('run');
      openPractice(fixture);
      writeCode(correctCode);
      cy.get('[data-cy="solution-code"]').focus();
      cy.press(Cypress.Keyboard.Keys.TAB);
      cy.get('[data-cy="solution-code"]').should('not.have.focus');
      cy.get('[data-cy="run-code"]').click();
      writeCode('// borrador posterior a la ejecución');
      cy.wait('@run', { responseTimeout: 45_000 })
        .its('response.statusCode')
        .should('eq', 201);
      cy.get('[data-cy="run-diagnosis"]').should('contain.text', 'SUCCESS');
      cy.get('[data-cy="stale-run"]').should('be.visible');
      cy.get('[data-cy="activity-progress"]')
        .should('contain.text', '0/1')
        .and('contain.text', 'Sin intentos');
      cy.get('[data-cy="attempt-history-row"]').should('not.exist');
      cy.contains('777113').should('not.exist');
      cy.get('[data-cy="practice-result"]').scrollIntoView();
      cy.screenshot('imp03-ejecucion', { capture: 'viewport' });
      cy.reload();
      cy.get('[data-cy="solution-code"]').should(
        'have.value',
        '// borrador posterior a la ejecución',
      );
      cy.get('[data-cy="practice-result"]').should('not.exist');
    });
  });
  it('IMP03-02 · Código incorrecto, sintaxis inválida y bucle infinito → diagnósticos distintos sin perder el borrador', () => {
    preparePractice().then((fixture) => {
      cy.intercept(
        'POST',
        `**${attemptsEndpoint(fixture).replace('/attempts', '/executions')}`,
      ).as('run');
      openPractice(fixture);
      for (const [code, diagnosis] of [
        ['function solve() { return 0; }', 'FAILED_TEST'],
        ['function solve( {', 'SYNTAX_ERROR'],
        ['function solve() { while (true) {} }', 'TIMEOUT'],
      ]) {
        writeCode(code!);
        cy.get('[data-cy="run-code"]').click();
        cy.wait('@run', { responseTimeout: 45_000 })
          .its('response.statusCode')
          .should('eq', 201);
        cy.get('[data-cy="run-diagnosis"]').should('contain.text', diagnosis!);
        cy.get('[data-cy="solution-code"]').should('have.value', code);
      }
      cy.get('[data-cy="attempt-history-row"]').should('not.exist');
    });
  });
  it('IMP03-09 · Fallar la consulta de avance y reintentar → muestra error sin inventar cero y recupera evidencia real', () => {
    preparePractice().then((fixture) => {
      let connectionFailed = true;
      cy.intercept(
        'GET',
        `**/api/v1/activities/${fixture.activity.id}/progress`,
        (request) => {
          // Fail only browser transport. Recovery reads the real API result.
          if (connectionFailed) request.destroy();
          else {
            request.alias = 'recoveredProgress';
            request.continue();
          }
        },
      );
      openPractice(fixture);
      cy.get('[data-cy="activity-progress"]').within(() => {
        cy.get('[role="alert"]').should('be.visible');
        cy.contains('Ejercicios requeridos completados:').should('not.exist');
        cy.contains('Sin intentos.').should('not.exist');
        cy.contains('0/1').should('not.exist');
      });
      cy.then(() => {
        connectionFailed = false;
      });
      cy.get('[data-cy="activity-progress"]')
        .contains('button', 'Reintentar consulta')
        .click();
      cy.wait('@recoveredProgress')
        .its('response.statusCode')
        .should('eq', 200);
      cy.get('[data-cy="activity-progress"]')
        .should('contain.text', '0/1')
        .and('contain.text', 'Sin intentos.');
      cy.get('[data-cy="activity-progress"] [role="alert"]').should(
        'not.exist',
      );
    });
  });
});
